                measureLkgReplay({
                    messages,
                    limit,
                    estimate: () =>
                        estimateFinalWireInputTokens({
                            messages,
                            toolDefinitionTokens,
                            systemPromptTokens: estimateTokens(JSON.stringify(system)),
