                sessionLog(draft.sessionID, "lkg replay input unavailable", error);
                return undefined;
            }
            const replayDraft = { ...draft, messages };
            return {
                draft: replayDraft,
                mapped: adaptPayload(replayDraft, admitted, times, anchorTimesOnly),
            };
        };
